practice.solution:
const out = [];
for (const item of $input.all()) {
  const body = item.json.body;
  for (const line of body.lines) {
    out.push({ json: {
      sku: line.sku,
      qty: line.qty,
      price: Number(line.price),
      email: body.customer.email.toLowerCase(),
    } });
  }
}
return out;

