const out = [];
for (const item of $input.all()) {
  const order = item.json.body;
  for (const li of order.line_items) {
    const unit = Number(li.price);
    const qty = Number(li.quantity);
    out.push({ json: {
      order: order.order_number,
      sku: li.sku,
      title: li.title,
      quantity: qty,
      unit_price: unit,
      line_total: Math.round(unit * qty * 100) / 100,
      customer_email: String(order.email).trim().toLowerCase(),
    } });
  }
}
return out;
